const SET_NOTE: Record<"clone" | "off" | "rag", string> = {
  clone: "Source: experiments/EXP-20261001-010-repaired-and-baselines/raw/lemkin-clone-v6.jsonl. Same prompts and budgets as the later adapters. 1 October 2026. Zero of 120 answers are only the topic. Clone v5 is the same weights, sampled again.",
  off: "Source: experiments/EXP-20261004-003-repaired-vs-relabel/raw/relabel.jsonl. Retrieval off, seed base 42, 4 October 2026. Selector pick. 20 of 30 X answers and 6 of 30 LinkedIn answers are only the topic.",
  rag: "Source: experiments/EXP-20261005-003-relabel-rag-final/raw/relabel.jsonl. Relabel plus factual RAG, 5 October 2026. 21 of 30 X answers and 6 of 30 LinkedIn answers are only the topic.",
};

export default function RelabelDrafts() {
  const theme = useHostTheme();
  const [setId, setSetId] = useCanvasState<"clone" | "off" | "rag">("run", "clone");
  const [medium, setMedium] = useCanvasState("medium", "all");
  const [topic, setTopic] = useCanvasState("topic", "all");
  const [ending, setEnding] = useCanvasState("ending", "all");

  const rows = DRAFTS[setId];
  const shown = useMemo(() => {
    return rows.filter((row) => {
      if (medium !== "all" && row.medium !== medium) return false;
      if (topic !== "all" && row.id !== topic) return false;
      if (ending === "cut" && row.finished) return false;
      if (ending === "done" && !row.finished) return false;
      return true;
    });
  }, [rows, medium, topic, ending]);

  const wordTotal = shown.reduce((sum, row) => sum + row.words, 0);
  const meanWords = shown.length ? Math.round(wordTotal / shown.length) : 0;
  const cut = shown.filter((row) => !row.finished).length;
  const early = shown.filter((row) => row.early).length;

  return (
    <Stack gap={20}>
      <Stack gap={6}>
        <H1>Drafts, same 30 topics</H1>
        <Text tone="secondary">
          Same prompts, four mediums. This page opens on clone v6, the latest
          full run where no answer is only the topic. Switch the run control
          for Relabel retrieval-off and Relabel plus RAG.
        </Text>
      </Stack>

      <Row gap={12} wrap align="end">
        <Stack gap={4} style={{ minWidth: 280 }}>
          <Text size="small" tone="tertiary">Run</Text>
          <Select
            value={setId}
            onChange={(value) => setSetId(value as "clone" | "off" | "rag")}
            options={[
              { value: "clone", label: "Clone v6, no title-only answers" },
              { value: "off", label: "Relabel, retrieval off" },
              { value: "rag", label: "Relabel plus RAG" },
            ]}
          />
        </Stack>
        <Stack gap={4} style={{ minWidth: 160 }}>
          <Text size="small" tone="tertiary">Medium</Text>
          <Select
            value={medium}
            onChange={setMedium}
            options={[
              { value: "all", label: "All mediums" },
              { value: "blog", label: "Blog" },
              { value: "linkedin", label: "LinkedIn" },
              { value: "x", label: "X" },
              { value: "talk", label: "Talk" },
            ]}
          />
        </Stack>
        <Stack gap={4} style={{ minWidth: 320, flex: 1 }}>
          <Text size="small" tone="tertiary">Topic</Text>
          <Select
            value={topic}
            onChange={setTopic}
            options={[{ value: "all", label: "All 30 topics" }, ...TOPICS]}
          />
        </Stack>
        <Stack gap={4} style={{ minWidth: 180 }}>
          <Text size="small" tone="tertiary">Ending</Text>
          <Select
            value={ending}
            onChange={setEnding}
            options={[
              { value: "all", label: "All endings" },
              { value: "done", label: "Sentence-final" },
              { value: "cut", label: "Mid-sentence" },
            ]}
          />
        </Stack>
      </Row>

      <Row gap={16} wrap>
        <Stat value={String(shown.length)} label="Drafts in view" />
        <Stat value={String(meanWords)} label="Mean words" />
        <Stat value={String(cut)} label="Mid-sentence endings" tone={cut > 0 ? "warning" : "success"} />
        {shown.some((row) => row.stop) ? (
        <Stat value={String(early)} label="Stopped under half budget" />
        ) : null}
      </Row>
      <Text size="small" tone="tertiary">{SET_NOTE[setId]}</Text>
      <Divider />

      {shown.map((row) => {
        const flags = [`${row.words} words`];
        if (row.stop === "length") flags.push("hit token limit");
        else if (row.stop === "eos") flags.push("end of sequence");
        flags.push(row.finished ? "sentence-final" : "mid-sentence");
        if (row.stop) {
          flags.push(row.early ? "under half the token budget" : "past half the token budget");
        }
        return (
          <Stack key={`${setId}-${row.id}-${row.medium}`} gap={8}>
            <Row gap={8} align="center" wrap>
              <Text weight="semibold">{row.id}</Text>
              <Text tone="secondary">{MEDIUM_LABEL[row.medium]}</Text>
              <Text size="small" tone="tertiary">{flags.join(" · ")}</Text>
            </Row>
            <H3>{row.topic}</H3>
            <div
              style={{
                background: theme.bg.elevated,
                padding: 16,
              }}
            >
              <Text style={{ whiteSpace: "pre-wrap", lineHeight: 1.6 }}>{row.answer}</Text>
            </div>
            <Divider />
          </Stack>
        );
      })}
    </Stack>
  );
}
